#include <cstddef>
#include <iostream>
#include <utility>

class DynArray
{
public:
    DynArray() = default;
    ~DynArray() { delete[] m_data; }

    // TODO: copy constructor and copy assignment (deep copy), move constructor and move assignment (steal)

    void push_back(int value)
    {
        if (m_size == m_capacity) reserve(m_capacity == 0 ? 4 : m_capacity * 2);
        m_data[m_size++] = value;
    }

    void reserve(std::size_t newCapacity)
    {
        if (newCapacity <= m_capacity) return;
        int* bigger{ new int[newCapacity] };
        for (std::size_t i{ 0 }; i < m_size; ++i) bigger[i] = m_data[i];
        delete[] m_data;
        m_data = bigger;
        m_capacity = newCapacity;
    }

    std::size_t size() const { return m_size; }
    int& operator[](std::size_t i) { return m_data[i]; }
    // TODO: pop_back, insert, erase, clear, at

private:
    int* m_data{ nullptr };
    std::size_t m_size{ 0 };
    std::size_t m_capacity{ 0 };
};

int main()
{
    DynArray a{};
    for (int i{ 0 }; i < 10; ++i) a.push_back(i * i);
    for (std::size_t i{ 0 }; i < a.size(); ++i) std::cout << a[i] << ' ';
    std::cout << '\n';
    return 0;
}
